#!/usr/bin/env bash
# Группа CI «fast-2» — вторая половина набора `not slow` (маркер slow не включён).
# v3.30: группы не перечисляют команды по одной; всё живёт в pytest, разбиение — по маркерам и
# именам, чтобы джобы шли параллельно и примерно равно по времени.
set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1   # байткод в дереве ломает проверку целостности managed
cd "$(dirname "$0")/../.."
# АРХИТЕКТУРНЫЙ ШАГ (2026-09-08, #465). Подробный разбор — в fast-1.sh. Здесь остаётся ровно всё,
# чего нет в fast-1: функции, чьё имя (и имя модуля) НЕ содержит `test_r/test_s/test_c/test_b`, —
# кластеры `test_a…`, `test_d/e/f/g/h/i/l/m/n/o/p/t/u/v/w…` и все будущие буквы. Партиция полная и
# непересекающаяся по построению (`not (набор fast-1)`), ни один тест не потерян и не гоняется дважды.
# Замер `--collect-only` (2026-09-08): fast-2 = 2848, fast-1 = 2757, сумма 5605 = весь `not slow`.
# Набор volume-bound (равный счёт ≈ равное время); границу уточнять по фактическим временам джоб CI.
# Новые тесты с прочими буквами копятся именно ЗДЕСЬ — при заметном перекосе двигать границу
# (перенести букву в fast-1) по замеру времён.
python3 -m pytest -n auto --dist loadfile tests/ -q -m "not slow" \
  -k "not (test_r or test_s or test_c or test_b)"
